const config = $('Scanner Config').first().json;
const finalizedHex = $input.first().json.result.number;
const finalizedNum = parseInt(finalizedHex, 16);
const safeHead = finalizedNum - (config.safetyLagBlocks || 5);
const staticData = $getWorkflowStaticData('global');
let lastBlock = staticData.lastScannedBlock || 0;
let startBlock;
if (!lastBlock || lastBlock <= 0) {
  startBlock = safeHead - (config.bootstrapLagBlocks || 20);
} else {
  startBlock = lastBlock + 1;
}
if (startBlock > safeHead) return [];
const maxBlocks = config.maxBlocksPerRun || 25;
const endBlock = Math.min(startBlock + maxBlocks - 1, safeHead);
const blockItems = [];
for (let b = startBlock; b <= endBlock; b++) {
  blockItems.push({ json: { rpcUrl: config.rpcUrl, blockNumber: b, blockHex: '0x' + b.toString(16), finalizedBlock: finalizedNum, safeHead, startBlock, endBlock } });
}
return blockItems;

const KNOWN_PROTOCOLS = new Map([
  ['0xc02aaa39b223fe8d0a0e5c4f27ead9083c756cc2', 'WETH9'],
  ['0x7a250d5630b4cf539739df2c5dacb4c659f2488d', 'UniswapV2Router'],
  ['0x68b3465833fb72a70ecdf485e0e4c7bd8665fc45', 'UniswapV3Router2'],
  ['0xe592427a0aece92de3edee1f18e0157c05861564', 'UniswapV3SwapRouter'],
  ['0x87870bca3f3fd6335c3f4ce8392d69350b4fa4e2', 'AaveV3Pool'],
  ['0xba12222222228d8ba445958a75a0704d566bf2c8', 'BalancerVault'],
  ['0xbebc44782c7db0a1a60cb6fe97d0b483032ff1c7', 'Curve3Pool'],
  ['0x1111111254eeb25477b68fb85ed929f73a960582', '1inchV5Router'],
  ['0xdef1c0ded9bec7f1a1670819833240f027b25eff', '0xExchangeProxy'],
  ['0x000000000022d473030f116ddee9f6b43ac78ba3', 'Permit2'],
  ['0x00000000219ab540356cbb839cbe05303d7705fa', 'BeaconDeposit'],
  ['0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48', 'USDC'],
  ['0xdac17f958d2ee523a2206206994597c13d831ec7', 'USDT'],
  ['0x6b175474e89094c44da98b954eedeac495271d0f', 'DAI']
]);

// Admission thresholds — these cut ~80% of low-value traffic
const MIN_GAS_LIMIT       = 50_000;   // ignore dust txs
const MIN_CALLDATA_BYTES  = 36;       // 4-byte selector + at least one 32-byte param (= 72 hex chars + 0x = 74 chars)
const MAX_QUEUE_PER_RUN   = 50;       // hard cap on what this single run adds

const candidates = [];

for (const item of $input.all()) {
  const block = item.json.result;
  if (!block || !block.transactions) continue;

  const blockNum = parseInt(block.number, 16);

  for (const tx of block.transactions) {
    const to      = (tx.to || '').toLowerCase();
    const input   = tx.input || '0x';
    const value   = tx.value || '0x0';
    const gasLim  = parseInt(tx.gas || '0x0', 16);
    const hasValue = value !== '0x0' && value !== '0x' && value !== '0';
    const calldataLen = (input.length - 2) / 2; // bytes

    let keep = false;
    let candidateType = '';
    let priorityScore = 0;

    // Tier 1 — contract creation: always keep
    if (!tx.to) {
      keep = true;
      candidateType = 'CONTRACT_CREATION';
      priorityScore = 90;
    }

    // Tier 2 — known high-value protocol: always keep
    else if (KNOWN_PROTOCOLS.has(to)) {
      keep = true;
      candidateType = 'KNOWN_PROTOCOL:' + KNOWN_PROTOCOLS.get(to);
      priorityScore = 100;
    }

    // Tier 3 — unknown contract call: strict admission
    // Must have: real calldata (not just a selector), meaningful gas, not a simple ETH transfer
    else if (
      calldataLen >= MIN_CALLDATA_BYTES &&
      gasLim >= MIN_GAS_LIMIT &&
      input !== '0x'
    ) {
      keep = true;
      candidateType = 'CONTRACT_CALL';
      priorityScore = 40;
      if (gasLim >= 200_000)  priorityScore += 20;
      if (gasLim >= 500_000)  priorityScore += 20;
      if (hasValue)           priorityScore += 10;
      if (calldataLen >= 200) priorityScore += 10; // complex calldata
    }

    // Everything else: ETH transfers, ERC20 approve-only calls, dust — skip
    if (!keep) continue;

    candidates.push({
      json: {
        txHash: tx.hash,
        blockNumber: blockNum,
        fromAddress: (tx.from || '').toLowerCase(),
        toAddress: to,
        gasLimit: gasLim,
        calldataBytes: calldataLen,
        value: tx.value,
        candidateType,
        priorityScore,
        status: 'DISCOVERED',
        discoveredAt: new Date().toISOString()
      }
    });

    if (candidates.length >= MAX_QUEUE_PER_RUN) break;
  }
  if (candidates.length >= MAX_QUEUE_PER_RUN) break;
}

// Sort best first before returning
candidates.sort((a, b) => b.json.priorityScore - a.json.priorityScore);
return candidates;

const items = $input.all();
const staticData = $getWorkflowStaticData('global');
if (!staticData.candidateQueue) staticData.candidateQueue = [];
let added = 0;
const existingHashes = new Set(staticData.candidateQueue.map(c => c.txHash));
let highestBlockInBatch = 0;
for (const item of items) {
  const c = item.json;
  if (c.blockNumber > highestBlockInBatch) highestBlockInBatch = c.blockNumber;
  if (!existingHashes.has(c.txHash)) { staticData.candidateQueue.push(c); existingHashes.add(c.txHash); added++; }
}
if (staticData.candidateQueue.length > 1000) {
  staticData.candidateQueue.sort((a,b) => b.priorityScore - a.priorityScore);
  staticData.candidateQueue = staticData.candidateQueue.slice(0, 1000);
}
if (highestBlockInBatch > (staticData.lastScannedBlock || 0)) {
  staticData.lastScannedBlock = highestBlockInBatch;
  staticData.lastScanTime = new Date().toISOString();
}
return [{ json: { discoveredThisRun: items.length, newlyQueued: added, totalQueueSize: staticData.candidateQueue.length, lastScannedBlock: staticData.lastScannedBlock, timestamp: new Date().toISOString() } }];
